/**
 * Payment Types — Sawaa Dashboard
 *
 * Every RESPONSE field is DERIVED from the committed OpenAPI snapshot
 * (`lib/types/api.generated.ts`, regenerated by `pnpm openapi:sync`). The
 * dashboard renders two different payment payloads with one type, so `Payment`
 * is a documented VIEW over them:
 *
 *  - `GET /dashboard/finance/payments` returns `PaymentListRowDto`: the payment
 *    row + `collectionDate` + an invoice projection WITHOUT `invoice.number`.
 *  - `GET /dashboard/finance/payments/:id` returns `PaymentDetailResponseDto`:
 *    the payment row + an invoice projection WITH `invoice.number` +
 *    `refundRequests`.
 *  - the refund / manual-refund / verify / bank-transfer routes return the bare
 *    payment row (`PaymentRecordDto`).
 *
 * Because one component tree consumes all three, `Payment` is the row plus the
 * optional union of the extra fields. `receipts` is a legacy dashboard-only
 * array: no current handler sends it (the backend moved to the singular
 * `receiptUrl`), and the UI guards it with a `.length` check, so keeping the
 * optional alias changes nothing at runtime.
 *
 * Money on payment rows is a Prisma `Decimal` (decimal string on the wire);
 * `PaymentStats` aggregates with `toNumber()` and is therefore numbers.
 */

import type { components } from "@/lib/types/api.generated"
import type {
  PaginatedQuery,
  PaymentMethod,
  PaymentStatus,
  TransferVerificationStatus,
} from "./common"

type Schemas = components["schemas"]

/* ─── Wire aliases (derived from OpenAPI) ─── */

/** One persisted payment row (`PaymentRecordDto`). */
export type PaymentRecord = Schemas["PaymentRecordDto"]

/** `GET /dashboard/finance/payments` row (`PaymentListRowDto`). */
export type PaymentListRow = Schemas["PaymentListRowDto"]

/** `GET /dashboard/finance/payments` envelope (`PaymentListResponseDto`). */
export type PaymentListPage = Schemas["PaymentListResponseDto"]

/** `GET /dashboard/finance/payments/:id` (`PaymentDetailResponseDto`). */
export type PaymentDetail = Schemas["PaymentDetailResponseDto"]

/** `GET /dashboard/finance/payments/stats` (`PaymentStatsResponseDto`). */
export type PaymentStats = Schemas["PaymentStatsResponseDto"]

/** Historical Booknetic collections (`PaymentHistoricalStatsDto`). */
export type HistoricalPaymentStats = Schemas["PaymentHistoricalStatsDto"]

/** Refund request row attached to a payment detail read (`PaymentRefundRequestRowDto`). */
export type PaymentRefundRequest = Schemas["PaymentRefundRequestRowDto"]

/** `POST /bookings/:bookingId/collect` payment branch (`PaymentCollectionPaymentDto`). */
export type CollectedPayment = Schemas["PaymentCollectionPaymentDto"]

/** `POST /bookings/:bookingId/collect` envelope (`PaymentCollectionResponseDto`). */
export type CollectBookingPaymentResult = Schemas["PaymentCollectionResponseDto"]

/** `POST /dashboard/finance/payments` (`PaymentProcessResponseDto`). */
export type PaymentProcessResponseDto = Schemas["PaymentProcessResponseDto"]
export type ProcessedPayment = PaymentProcessResponseDto

/** Body of `POST /bookings/:bookingId/collect` (`CollectBookingPaymentDto`). */
export type CollectBookingPaymentPayload = Schemas["CollectBookingPaymentDto"]

/* ─── Dashboard view over the three payment payloads ─── */

/** Invoice projection as the list route sends it (no `number`). */
type PaymentListInvoice = NonNullable<PaymentListRow["invoice"]>
/** Invoice projection as the detail route sends it (has `number`). */
type PaymentDetailInvoice = NonNullable<PaymentDetail["invoice"]>

/**
 * Legacy bank-transfer receipt array. The backend no longer sends it; the
 * detail dialog only renders it behind a truthiness check, so the alias is
 * retained to keep the historical branch compiling. Never produced today.
 */
export interface BankTransferReceipt {
  id: string
  receiptUrl: string
  aiVerificationStatus: TransferVerificationStatus
  aiConfidence: number | null
  aiNotes: string | null
  adminNotes: string | null
  reviewedAt: string | null
  createdAt: string
}

/** Payment row plus the optional extras the list/detail views add. */
export type Payment = PaymentRecord & {
  /** Only the list route adds it. */
  collectionDate?: PaymentListRow["collectionDate"]
  /**
   * Invoice projection. `number` is optional because the list projection omits
   * it; the detail projection always has it.
   */
  invoice?: (PaymentListInvoice & { number?: PaymentDetailInvoice["number"] }) | null
  /** Only the detail route adds it. */
  refundRequests?: PaymentDetail["refundRequests"]
  /** Legacy dashboard-only array; no handler sends it today. */
  receipts?: BankTransferReceipt[]
}

/* ─── Query (client-side; mapped onto ListPaymentsDto by lib/api/payments) ─── */

export interface PaymentListQuery extends PaginatedQuery {
  search?: string
  status?: PaymentStatus
  method?: PaymentMethod
  dateFrom?: string
  dateTo?: string
}

/* ─── Write payloads (mirror the request DTOs) ─── */

/** Body of `PATCH /payments/:id/refund`, mirrored from `RefundPaymentDto`. */
export type RefundPayload = Schemas["RefundPaymentDto"]

/** Body of `PATCH /payments/:id/manual-refund`, mirrored from `ManualRefundPaymentDto`. */
export type ManualRefundPayload = Schemas["ManualRefundPaymentDto"]

/** Body of `PATCH /payments/:id/verify`, mirrored from `VerifyPaymentDto`. */
export type VerifyPaymentPayload = Schemas["VerifyPaymentDto"]
